```openscad
// Round-bottom flask support ring on three legs
// Print orientation: legs stand on the bed (z = 0), ring at the top

$fn = 96;

// ---- Ring ----
ring_od        = 70;    // ring outer diameter
ring_id        = 54;    // ring inner diameter
ring_thick     = 5;     // ring thickness (Z)
ring_top_z     = 50;    // Z of ring top face

// ---- Legs ----
leg_d          = 6;     // leg diameter
leg_circle_d   = 62;    // diameter of circle through leg axes
leg_count      = 3;     // number of legs
leg_start_ang  = 0;     // first leg on +X axis
leg_overlap    = 0.5;   // legs extend this far into the ring for a solid union

// ---- Derived ----
ring_bot_z     = ring_top_z - ring_thick;
cut_ext        = 0.5;   // cutter extension past faces

union() {
    // Flat ring (annulus)
    translate([0, 0, ring_bot_z])
        difference() {
            cylinder(h = ring_thick, d = ring_od);
            translate([0, 0, -cut_ext])
                cylinder(h = ring_thick + 2 * cut_ext, d = ring_id);
        }

    // Legs
    for (i = [0 : leg_count - 1]) {
        a = leg_start_ang + i * 360 / leg_count;
        translate([leg_circle_d / 2 * cos(a), leg_circle_d / 2 * sin(a), 0])
            cylinder(h = ring_bot_z + leg_overlap, d = leg_d);
    }
}
```

