// Spacer with counterbored socket-head screw hole
// Print orientation: standing on bed, z = 0 to 12, centred on origin

// ---------------- Parameters ----------------
body_d      = 24;    // outer diameter of spacer
body_h      = 12;    // total height of spacer
hole_d      = 3.4;   // through-hole diameter (screw clearance)
cbore_d     = 6.5;   // counterbore diameter (screw head)
cbore_depth = 5;     // counterbore depth from top face (z = 7 to 12)
eps         = 0.5;   // overshoot for clean boolean cuts
$fn         = 96;    // smoothness of curved surfaces

// ---------------- Model ----------------
difference() {
    // Main cylindrical body
    cylinder(d = body_d, h = body_h);

    // Through-hole along the axis
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = body_h + 2 * eps);

    // Counterbore from the top face
    translate([0, 0, body_h - cbore_depth])
        cylinder(d = cbore_d, h = cbore_depth + eps);
}
