```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate flat on bed, rail pointing up (+Z)

$fn = 64;

// ---------------- Dimensions (mm) ----------------
plate_len    = 100;   // base plate length (X)
plate_wid    = 30;    // base plate width (Y)
plate_thk    = 4;     // base plate thickness (Z), z = 0..4

rail_len     = plate_len; // rail runs full length of plate (X)
rail_w_bot   = 12;    // rail width where it meets plate (at z = plate_thk)
rail_w_top   = 16;    // rail width at top face
rail_top_z   = 12;    // absolute Z of rail top face
rail_h       = rail_top_z - plate_thk; // rail height above plate (8)

overlap      = 0.1;   // rail embedded into plate to avoid coplanar union faces

// Width of the flared rail extended down by 'overlap' (keeps same flank angle)
flare_per_mm = (rail_w_top - rail_w_bot) / rail_h;          // width change per mm height
rail_w_emb   = rail_w_bot - flare_per_mm * overlap;          // width at z = plate_thk - overlap

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: trapezoid in YZ, extruded along X
    // rotate([90,0,90]) maps 2D (u,v) -> (Y,Z), extrusion axis -> X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_w_emb/2, plate_thk - overlap],
                [ rail_w_emb/2, plate_thk - overlap],
                [ rail_w_top/2, rail_top_z],
                [-rail_w_top/2, rail_top_z]
            ]);
}
```

