// Sliding mount with dovetail rail
// Print orientation: base plate on bed, rail pointing up (+Z)

$fn = 64;

// ---- Base plate ----
plate_len   = 60;   // X length of base plate
plate_wid   = 30;   // Y width of base plate
plate_thk   = 5;    // Z thickness of base plate (z = 0..5)

// ---- Dovetail rail ----
rail_len     = plate_len; // rail runs full length of plate
rail_bot_w   = 12;  // rail width where it meets plate (z = 5)
rail_top_w   = 18;  // rail width at top face (z = 10)
rail_top_z   = 10;  // Z of rail top face
rail_overlap = 0.5; // rail extends this far down into plate for a clean union

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module dovetail_rail() {
    // Trapezoid drawn in (Y, Z), extruded along X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_bot_w/2, plate_thk - rail_overlap], // hidden inside plate
                [ rail_bot_w/2, plate_thk - rail_overlap],
                [ rail_bot_w/2, plate_thk],                // root of dovetail
                [ rail_top_w/2, rail_top_z],               // flared top edge
                [-rail_top_w/2, rail_top_z],
                [-rail_bot_w/2, plate_thk]
            ]);
}

union() {
    base_plate();
    dovetail_rail();
}
