```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate on bed (z = 0), rail on top, building +Z

$fn = 64;

// ---------- Base plate ----------
plate_len   = 80;   // X length of base plate
plate_wid   = 40;   // Y width of base plate
plate_thk   = 5;    // Z thickness of base plate (z = 0..5)

// ---------- Dovetail rail ----------
rail_len    = plate_len; // rail runs full plate length (X)
rail_w_bot  = 10;   // rail width where it meets the plate (z = 5)
rail_w_top  = 14;   // rail width at its top face (z = 11)
rail_top_z  = 11;   // Z height of rail top face
rail_h      = rail_top_z - plate_thk; // rail height (6 mm)

// ---------- Construction ----------
overlap     = 0.01; // small embed of rail into plate for a clean union

// Width of rail at a given height above the plate (linear flare)
function rail_w_at(h) = rail_w_bot + (rail_w_top - rail_w_bot) * h / rail_h;

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module dovetail_rail() {
    w0 = rail_w_at(-overlap);   // width slightly below plate top (embedded)
    // 2D profile: local x -> Y, local y -> Z; extruded along X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-w0/2,          plate_thk - overlap],
                [ w0/2,          plate_thk - overlap],
                [ rail_w_top/2,  rail_top_z],
                [-rail_w_top/2,  rail_top_z]
            ]);
}

union() {
    base_plate();
    dovetail_rail();
}
