// Sliding mount with dovetail rail
// Print orientation: base plate flat on the bed, rail pointing up (+Z)

$fn = 64;

// ---------- Base plate ----------
plate_len   = 120;   // plate length along X
plate_wid   = 40;    // plate width along Y
plate_thk   = 4;     // plate thickness (z = 0 to 4)

// ---------- Dovetail rail ----------
rail_len    = plate_len; // rail runs the full plate length
rail_base_w = 10;    // rail width where it meets the plate (z = 4)
rail_top_w  = 16;    // rail width at its top face (z = 9)
rail_top_z  = 9;     // z height of the rail's top face
rail_h      = rail_top_z - plate_thk; // rail height (5 mm)

overlap     = 0.01;  // small embed of rail into plate for a clean union

// Rail width at the embedded bottom (z = plate_thk - overlap), keeping the flank angle
flare_per_mm = (rail_top_w - rail_base_w) / rail_h;   // total width change per mm of height
rail_emb_w   = rail_base_w - flare_per_mm * overlap;

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module dovetail_rail() {
    // Trapezoid drawn in 2D (local x -> world Y, local y -> world Z),
    // extruded along world X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_emb_w/2, plate_thk - overlap],
                [ rail_emb_w/2, plate_thk - overlap],
                [ rail_top_w/2, rail_top_z],
                [-rail_top_w/2, rail_top_z]
            ]);
}

union() {
    base_plate();
    dovetail_rail();
}
