        // Boss (overlaps the disc slightly so the two solids fuse)
        translate([0, 0, disc_h - eps])
            cylinder(d = boss_d, h = boss_top_z - disc_h + eps);
    }

    // Rod hole: from z = 2 up through the top of the boss
    translate([0, 0, hole_floor])
        cylinder(d = hole_d, h = boss_top_z - hole_floor + eps);
}
