```openscad
// Door wedge with vertical through-slot
// Print orientation: flat bottom face on the bed (z = 0), sloped face upward.
// The user's coordinates place the wedge at x = 0..80 and y = 0..40.

// ---------------- Parameters ----------------
wedge_length = 80;   // X length of the wedge
wedge_width  = 40;   // Y width (extrusion depth)
wedge_height = 20;   // Z height at x = 0

slot_width   = 6;    // slot size in Y
slot_length  = 30;   // slot size in X
slot_cx      = 40;   // slot centre X
slot_cy      = 20;   // slot centre Y

eps          = 1;    // overshoot so cutters pass fully through faces

$fn = 64;

// ---------------- Modules ----------------
module wedge_body() {
    // Draw the triangle in the XY plane, extrude it along +Z, then
    // rotate +90 deg about X so the profile lies in XZ.
    // After rotation the extrusion runs along -Y, so shift it by +wedge_width.
    translate([0, wedge_width, 0])
        rotate([90, 0, 0])
            linear_extrude(height = wedge_width)
                polygon(points = [
                    [0, 0],
                    [wedge_length, 0],
                    [0, wedge_height]
                ]);
}

module slot_cutter() {
    // Starts below z = 0 and ends above z = wedge_height,
    // so the cut passes through every face it meets.
    translate([slot_cx - slot_length / 2,
               slot_cy - slot_width / 2,
               -eps])
        cube([slot_length, slot_width, wedge_height + 2 * eps]);
}

// ---------------- Part ----------------
difference() {
    wedge_body();
    slot_cutter();
}
```

