```openscad
// Glass stirring rod rest - rectangular block with V-grooves
// Units: mm

$fn = 64;

// --- Block dimensions ---
block_len   = 66;   // length along X
block_wid   = 30;   // width along Y
block_ht    = 15;   // height along Z

// --- Groove parameters ---
groove_count = 3;   // number of V-grooves
groove_pitch = 18;  // centre-to-centre spacing along X
groove_top_w = 10;  // groove width at top surface
groove_depth = 5;   // groove depth (90-degree V: half-width = depth)

// --- Cutting overlap ---
eps = 1;            // extension past cut faces

// Derived: extend the V above the top face while keeping the 90-degree angle
cut_top_z  = block_ht + eps;
cut_half_w = groove_top_w / 2 + eps;   // 45-degree walls: +1 height adds +1 half-width
apex_z     = block_ht - groove_depth;

difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // V-grooves running full width along Y
    for (i = [0 : groove_count - 1]) {
        gx = (i - (groove_count - 1) / 2) * groove_pitch;
        rotate([90, 0, 0])
            linear_extrude(height = block_wid + 2 * eps, center = true)
                polygon([
                    [gx - cut_half_w, cut_top_z],
                    [gx + cut_half_w, cut_top_z],
                    [gx,              apex_z]
                ]);
    }
}
