// Glass stirring rod rest - block with 5 V-grooves across the top
// Print orientation: flat on bed, grooves facing up

$fn = 64;

// ---- Block dimensions ----
block_len   = 84;   // X length (mm)
block_wid   = 40;   // Y width (mm)
block_h     = 18;   // Z height (mm)

// ---- Groove parameters ----
groove_count = 5;   // number of V-grooves
groove_pitch = 15;  // centre-to-centre spacing along X (mm)
groove_top_w = 8;   // V width at the top surface (mm)
groove_depth = 4;   // V depth (mm) -> 90 deg included angle
overcut      = 0.5; // extra cutter extension past faces (mm)

// Derived
half_top = groove_top_w / 2;          // 4 mm half-width at top
slope    = half_top / groove_depth;   // 1.0 for 90 deg V

module v_groove_cutter() {
    // V profile in XZ, apex at z = block_h - groove_depth,
    // extended above top surface along the same 90-degree flanks
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * overcut, center = true)
            polygon(points = [
                [0, block_h - groove_depth],
                [ half_top + overcut * slope, block_h + overcut],
                [-(half_top + overcut * slope), block_h + overcut]
            ]);
}

difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // V-grooves running full width along Y, centred along X
    for (i = [0 : groove_count - 1])
        translate([(i - (groove_count - 1) / 2) * groove_pitch, 0, 0])
