// Captive hex-nut clamping block
// Print orientation: bottom face (with hex pocket) on the bed, z = 0

// ---- Block ----
block_x      = 24;    // block length in X (mm)
block_y      = 24;    // block width in Y (mm)
block_z      = 12;    // block height in Z (mm)

// ---- Through hole ----
hole_d       = 4.5;   // vertical through-hole diameter (mm)

// ---- Hex nut pocket (cut from bottom face) ----
hex_af       = 7.2;   // hex pocket size across flats (mm)
hex_depth    = 3.4;   // hex pocket depth from bottom face (mm)
hex_r        = hex_af / (2 * cos(30)); // circumradius from across-flats (mm)

// ---- Misc ----
eps          = 0.5;   // overshoot for clean cuts (mm)
$fn          = 96;    // resolution for round features

difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_x/2, -block_y/2, 0])
        cube([block_x, block_y, block_z]);

    // Vertical through hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = block_z + 2*eps);

    // Hex pocket from bottom face.
    // circle($fn=6) puts vertices on the X axis, so the top and bottom
    // flats (at y = +/- hex_af/2) are parallel to the X axis.
    translate([0, 0, -eps])
        linear_extrude(height = hex_depth + eps)
            circle(r = hex_r, $fn = 6);
}
