// Stepped riser - solid staircase of 3 equal steps
// Print orientation: rests on bed (z = 0), climbs in +X, extruded along +Y

// ---------------- Parameters ----------------
n_steps     = 3;    // number of steps
step_length = 10;   // length of each step in X (mm)
step_rise   = 8;    // height increase per step (mm); first step height = 8
depth_y     = 20;   // extrusion depth along Y (mm), from y = 0 to y = 20

$fn = 64;           // curve resolution (no curved features, kept for consistency)

// Derived
total_length = n_steps * step_length;   // 30 mm
total_height = n_steps * step_rise;     // 24 mm

// ---------------- Profile (in XZ) ----------------
// Points of the staircase outline: start at origin, run along bed,
// up the back face, then descend the steps back toward x = 0.
profile_pts = concat(
    [[0, 0], [total_length, 0]],
    [ for (i = [n_steps - 1 : -1 : 0])
        each [
            [(i + 1) * step_length, (i + 1) * step_rise],  // outer corner of step i
            [ i      * step_length, (i + 1) * step_rise]   // inner corner of step i
        ]
    ]
);

// ---------------- Model ----------------
// Profile drawn in 2D X/Y, extruded, then rotated so 2D Y -> world Z.
// rotate([90,0,0]) sends extrusion to -Y, so shift by depth_y to span y = 0..20.
translate([0, depth_y, 0])
    rotate([90, 0, 0])
        linear_extrude(height = depth_y)
            polygon(points = profile_pts);
```

