// Stepped riser - 3 equal solid steps climbing in +X
// Positioned per user coordinates: x = 0..30, y = 0..30, z = 0 up
// (user specified explicit coordinates, so not centred on origin)

num_steps   = 3;    // number of steps
step_len    = 10;   // length of each step along X (mm)
step_rise   = 8;    // height increase per step (mm); first step height = 8
riser_depth = 30;   // extrusion length along Y (mm)
overlap     = 0.01; // small overlap so adjacent blocks fuse cleanly

union() {
    for (i = [0 : num_steps - 1]) {
        // each step is a solid block from the bed up to its tread height
        translate([i * step_len - (i > 0 ? overlap : 0), 0, 0])
            cube([step_len + (i > 0 ? overlap : 0),
                  riser_depth,
                  (i + 1) * step_rise]);
    }
}
