```openscad
// Gas cylinder label tag
// Flat plate with rounded corners and a cable-tie hole

// ---------- Dimensions (mm) ----------
plate_length   = 80;    // overall length along X
plate_width    = 25;    // overall width along Y
plate_thick    = 3;     // plate thickness along Z
corner_radius  = 4;     // corner radius (seen from above)

hole_diameter  = 6;     // cable tie hole diameter
hole_x         = -34;   // hole centre X position
hole_y         = 0;     // hole centre Y position

cut_overlap    = 0.5;   // extra length on cutters to avoid coplanar faces

$fn = 64;               // resolution for curved shapes

// ---------- Modules ----------
module rounded_plate(l, w, t, r) {
    // Hull of four corner cylinders gives a rounded rectangle
    hull() {
        for (sx = [-1, 1], sy = [-1, 1]) {
            translate([sx * (l / 2 - r), sy * (w / 2 - r), 0])
                cylinder(h = t, r = r, $fn = 64);
        }
    }
}

// ---------- Part ----------
difference() {
    rounded_plate(plate_length, plate_width, plate_thick, corner_radius);

    // Cable tie hole through the plate
    translate([hole_x, hole_y, -cut_overlap])
        cylinder(h = plate_thick + 2 * cut_overlap, d = hole_diameter, $fn = 64);
}
